def find_min_sum(n):
    def sieve_of_eratosthenes(limit):
        is_prime = [True] * (limit + 1)
        p = 2
        while (p * p <= limit):
            if (is_prime[p] == True):
                for i in range(p * p, limit + 1, p):
                    is_prime[i] = False
            p += 1

        return [num for num in range(2, limit + 1) if is_prime[num]]

    # Generate all prime factors of n
    prime_factors = sieve_of_eratosthenes(n)

    # Calculate the sum of the prime factors
    min_sum = sum(prime_factors)

    return min_sum

