def find_Min_Sum(n):
    # Initialize the min_sum to infinity
    min_sum = float('inf')

    # Loop through all numbers from 1 to n
    for i in range(1, n + 1):
        # If 'i' divides 'n', it's a factor
        if n % i == 0:
            # Calculate the sum of the divisors including 'i'
            sum_divisors = i + (n // i)
            # Update the min_sum if the current sum is smaller
            if sum_divisors < min_sum:
                min_sum = sum_divisors

    return min_sum

