def find_Min_Sum(n):
    # Initialize sum with 1 because 1 is the smallest factor of any number
    min_sum = 1

    # Loop through possible divisors starting from 2 up to the square root of n
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            # Add the current divisor to the sum and divide n by it
            min_sum += i
            n //= i

    # If n is greater than 1 after all divisions, add it to the sum
    if n > 1:
        min_sum += n

    return min_sum

