def modular_sum(nums, n, m):
    # Check if any number is already divisible by m
    for i in range(n):
        if nums[i] % m == 0:
            return True

    # Check all possible subsets using bitmasking
    for i in range(1 << n):
        total = 0
        for j in range(n):
            if (i & (1 << j)) != 0:
                total += nums[j]
        if total % m == 0:
            return True

    return False

