def modular_sum(arr, n, m):
    # Check if sum of all elements is divisible by m
    if (sum(arr)) % m != 0:
        return False

    # Create a matrix to store subproblems
    dp = [[False] * (m + 1) for _ in range(n + 1)]

    # Initialize the first row and first column of the dp matrix
    for i in range(n + 1):
        dp[i][0] = True
    for j in range(1, m + 1):
        dp[0][j] = False

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if arr[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][m]

