def modular_sum(arr, n, m):
    # Helper function to calculate the maximum sum possible considering all subsets
    def find_max_sum():
        max_sum = -float('inf')
        for i in range(1 << n):
            current_sum = 0
            for j in range(n):
                if (i & (1 << j)):
                    current_sum += arr[j]
            if (current_sum % m == 0):
                max_sum = max(max_sum, current_sum)
        return max_sum

    # Calculate the maximum possible sum modulo m
    max_modulo = find_max_sum()

    # If the maximum modulo is positive and less than m, then there exists a subset with sum divisible by m
    return max_modulo > 0 and max_modulo < m

