def calculate_gcd(x, y):
    # Base case: if one number is zero, the GCD is the other number
    if x == 0:
        return y
    elif y == 0:
        return x
    else:
        # Recursive case: apply Euclidean algorithm
        return calculate_gcd(y, x % y)

