    # Initialize the result as 1 since 1 is the LCM of any set of numbers
    result = 1

    # Loop through each element in the array
    for num in arr:
        # Calculate GCD of result and current number
        gcd = calculate_gcd(result, num)
        # Update result by multiplying with the GCD
        result = (result * num) // gcd

    return result

