    max_so_far = arr[0]
    for i in range(1, n):
        if arr[i] > max_so_far:
            max_so_far = arr[i]
            left_max[i] = max_so_far
        else:
            left_max[i] = max_so_far

    # Fill right_max array
    max_so_far = arr[n-1]
    for i in range(n-2, -1, -1):
