            max_so_far = arr[i]
            right_max[i] = max_so_far
        else:
            right_max[i] = max_so_far

    # Calculate length of Longest Bitonic Subsequence
    lbs_length = 0
    for i in range(n):
        lbs_length = max(lbs_length, left_max[i] + right_max[i] - 1)

    return lbs_length

