    # Initialize the array for decreasing subsequence
    dec = [1] * n

    # Fill the decreasing subsequence array
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Calculate the length of the longest bitonic subsequence
    max_lbs = 0
    for i in range(n):
        max_lbs = max(max_lbs, inc[i] + dec[i] - 1)  # Subtract 1 because the element is counted twice

