        return 0

    # Initialize the list to store the maximum sum up to each index
    dp = [num for num in nums]

    # Iterate through the array starting from the second element
    for i in range(1, len(nums)):
        # Update dp[i] to be the maximum of dp[i] and dp[j] + nums[i] where j < i
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + nums[i])

    # Return the maximum value in dp which is the result
    return max(dp)

