def min_coins(coins, amount, target):
    # If amount is less than or equal to 0, no need to proceed
    if amount <= 0:
        return 0

    # If target is 0, no coins are needed
    if target == 0:
        return 1

    # Initialize the count of coins to 0
    count = float('inf')

    # Iterate through each coin available
    for coin in coins:
        if coin <= amount:
            # Recursively calculate the minimum coins needed for the remaining amount
            temp_count = min_coins(coins, amount - coin, target)

            # Update the count of coins if a lower count is found
            if temp_count != float('inf'):
                count = min(count, 1 + temp_count)

    return count

