def min_coins(coins, target, count):
    # Base case: if target is less than or equal to 0, return the count
    if target <= 0:
        return count
    # If no more coins left, return infinity (indicating no solution)
    if not coins:
        return float('inf')

    # Recursive case: consider using the current coin or not
    use_coin = min_coins(coins[1:], target - coins[0], count + 1)
    dont_use_coin = min_coins(coins[1:], target, count)

    # Return the minimum between using and not using the current coin
    return min(use_coin, dont_use_coin)

