def min_coins(coins, amount, n):
    # If the total amount is 0, no coins are needed
    if amount == 0:
        return 0

    # If no more coins are left, the total amount cannot be made
    if n == 0 and amount > 0:
        return float('inf')

    # If the current coin can be used to make the amount
    if coins[n - 1] <= amount:
        # Return the minimum between using or not using the current coin
        return min(1 + min_coins(coins, amount - coins[n - 1], n), min_coins(coins, amount, n - 1))
    else:
        # If the current coin cannot be used, skip it and move to the next coin
        return min_coins(coins, amount, n - 1)

