def check_permutation(str1, str2):
    # Check if lengths of both strings are equal
    if len(str1) != len(str2):
        return False

    # Count occurrences of each character in both strings
    char_count = {}

    for char in str1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in str2:
        if char not in char_count or char_count[char] == 0:
            return False
        char_count[char] -= 1

    # If all characters have been counted and no more remain, they are permutations
    return True

