def Total_Hamming_Distance(n):
    total = 0
    # Iterate through each pair of consecutive numbers from 0 to n-1
    for i in range(n):
        # For each pair, add their Hamming distance to the total
        total += Hamming_distance(i, i + 1)
    return total

