def longest_increasing_subsequence(sequence):
    # Initialize the list to keep track of the length of the LIS up to each index
    lis_length = [1] * len(sequence)

    # Calculate the length of the LIS for each element in the sequence
    for i in range(1, len(sequence)):
        for j in range(i):
            if sequence[j] < sequence[i]:
                lis_length[i] = max(lis_length[i], lis_length[j] + 1)

    # The length of the longest increasing subsequence is the maximum value in the lis_length list
    return max(lis_length)

