def digit_distance_nums(a, b):
    # Convert both numbers to strings to iterate over each digit
    num_a_str = str(a)
    num_b_str = str(b)

    # Initialize variables to store the difference between corresponding digits
    diff_sum = 0

    # Iterate over the lengths of the two number strings
    for i in range(min(len(num_a_str), len(num_b_str))):
        # Calculate the absolute difference and add it to the sum
        diff_sum += abs(int(num_a_str[i]) - int(num_b_str[i]))

    # If one number is longer than the other, add the remaining digits' differences
    if len(num_a_str) > len(num_b_str):
        for j in range(i + 1, len(num_a_str)):
            diff_sum += abs(int(num_a_str[j]) - 0)  # Assuming 0 represents the missing digit in the shorter number
    elif len(num_b_str) > len(num_a_str):
        for j in range(i + 1, len(num_b_str)):
            diff_sum += abs(int(num_b_str[j]) - 0)  # Assuming 0 represents the missing digit in the shorter number

    return diff_sum

