def assign_elements(tuples_list):
    # Create an empty dictionary to store the result
    result = {}

    # Iterate over each tuple in the list
    for t in tuples_list:
        # Check if the first element of the tuple is already in the result dictionary
        if t[0] in result:
            # Append the second element of the current tuple to the list associated with the first element
            result[t[0]].append(t[1])
        else:
            # If the first element is not in the result dictionary, create a new entry with the first element as key and the second element as value
            result[t[0]] = [t[1]]

