def extract_even(mixed_tuple):
    """
    Extracts and returns only the even numbers from a deeply nested tuple.

    Args:
    mixed_tuple: A tuple containing elements that can be integers or other tuples.

    Returns:
    A tuple containing only the even numbers found within the original tuple.
    """
    # Use recursion to handle nested structures
    def extract_even_helper(sub_tuple):
        for element in sub_tuple:
            if isinstance(element, int) and element % 2 == 0:
                yield element
            elif isinstance(element, tuple):
                yield from extract_even_helper(element)

    # Filter out even numbers using generator expression and convert to tuple
    return tuple(extract_even_helper(mixed_tuple))

