import re

def find_adverbs(sentence):
    # Use regex to find all occurrences of words ending with "ly" as they indicate adverbs
    adverbs = [match.group() for match in re.finditer(r'\b\w+ly\b', sentence)]

    # If adverbs are found, format their positions in the sentence and return them as a string
    if adverbs:
        positions = [(match.start(), match.end()) for match in re.finditer(r'\b\w+ly\b', sentence)]
        return '{0}-{1}: {2}'.format(*positions[0], ', '.join(adverbs))
    else:
        return 'No adverbs found.'

# Example usage
print(find_adverbs("Clearly, he has no excuse for such behavior."))  # Output: 0-7: Clearly

