    even_sum = 0
    odd_sum = 0

    # Iterate through each number in the list
    for num in nums:
        # Check if the number is even
        if num % 2 == 0:
            even_sum += num
        # If the number is odd
        else:
            odd_sum += num

    # Calculate and return the difference between the sums of even and odd numbers
    return abs(even_sum - odd_sum)

