def find_kth(arr1, arr2, n1, n2, k):
    # If k is more than the total length of both arrays, return -1
    if (n1 + n2 < k):
        return -1

    i = j = 0
    while i < n1 and j < n2:
        if arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1
        k -= 1

    if i == n1:
        return arr2[j+k-1]

    if j == n2:
        return arr1[i+k-1]

