def find_kth(arr1, arr2, x, y, k):
    # Base cases
    if x == 0:
        return arr2[y - k]
    elif y == 0:
        return arr1[x - k]

    # Compare the elements at the current positions of both arrays
    if arr1[x - 1] <= arr2[y - 1]:
        # If the element in arr1 is smaller or equal, move the pointer in arr1 one step forward
        return find_kth(arr1[x - 1:], arr2, x - 1, y, k)
    else:
        # Otherwise, move the pointer in arr2 one step forward
        return find_kth(arr1, arr2[y - 1:], x, y - 1, k - 1)

