def find_kth(arr1, arr2, k1, k2, n):
    # Check if k is within the range of both arrays
    if k1 > n or k2 > n:
        return "k is out of bounds"

    # If one array is empty, the k-th element is the k-th element of the other array
    if len(arr1) == 0: 
        return arr2[k2 - 1]
    elif len(arr2) == 0: 
        return arr1[k1 - 1]

    # If we have not reached the k-th element yet, move forward in the appropriate array
    if k1 < k2: 
        return find_kth(arr1[1:], arr2, k1 + 1, k2, n)
    else: 
        return find_kth(arr1, arr2[1:], k1, k2 + 1, n)

